public static async Task<Dictionary<int, int>> GetTotalViewsPerBlogAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken = default)
{
    var query =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId into blogPosts
        select new { BlogId = blogPosts.Key, TotalViews = blogPosts.Sum(p => p.Views) };

    var totals = await query.ToDictionaryAsync(x => x.BlogId, x => x.TotalViews, cancellationToken);

    return totals;
}
```

