public async Task RenamePostAsync(BlogContext context, int postId, string newTitle, CancellationToken cancellationToken)
{
    var postQuery =
        from post in context.Posts
        where post.Id == postId
        select post;

    var matchingPosts = await postQuery.ToListAsync(cancellationToken);
    var existingPost = matchingPosts.Single();

    existingPost.Title = newTitle;

    await context.SaveChangesAsync(cancellationToken);
}
